import{_ as n,C as a,c as i,o as l,a3 as t,G as o,j as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Lots and serial numbers","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/workflows/lots-and-serial-numbers.md","filePath":"master/supply-chain/manufacturing/workflows/lots-and-serial-numbers.md","lastUpdated":1791902625000}'),u={name:"master/supply-chain/manufacturing/workflows/lots-and-serial-numbers.md"};function c(d,e,m,h,g,p){const r=a("ImagePopup");return l(),i("div",null,[e[0]||(e[0]=t('<h1 id="lots-and-serial-numbers" tabindex="-1">Lots and serial numbers <a class="header-anchor" href="#lots-and-serial-numbers" aria-label="Permalink to &quot;Lots and serial numbers&quot;">​</a></h1><p>A lot is a batch of identical goods. A serial number marks one single unit. In manufacturing, you use them to trace a finished product, or a component, back to where it came from. The register of all numbers sits under the Manufacturing menu.</p><blockquote><p><strong>In simple words:</strong> A lot or serial number is a label that lets you follow one batch or one unit through stock.</p></blockquote><p>Open <code>Manufacturing → Products → Lots / Serial Numbers</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The page works with the tracking set in Inventory. Go to <code>Inventory → Settings → Manage Traceability</code> and turn on <strong>Lots &amp; Serial Numbers</strong>. Then open the product in Inventory, turn on <strong>Track Inventory</strong> and set <strong>Track By</strong> to <strong>By Lots</strong> or <strong>By Unique Serial Number</strong>.</p><p>The Inventory guide explains this in full. See <a href="./../../inventories/tracking/lots-and-serial-numbers.html">Lots and serial numbers (Inventory)</a>. For the product side, see <a href="./../basic-setup/configure-product.html">Configure product</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The page is the same register that Inventory uses. A number you create here is visible in Inventory, and the other way round.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',9)),o(r,{src:"/images1/manufacturing/lot_list.png",alt:"Lots / Serial Numbers list under Manufacturing → Products with rows and the New Lot / Serial Number button"}),e[1]||(e[1]=t('<ul><li><strong>Columns:</strong> <strong>Name</strong>, <strong>Product</strong>, <strong>Internal Reference</strong>, <strong>On Hand Quantity</strong>.</li><li><strong>Button:</strong> <strong>New Lot / Serial Number</strong>.</li></ul><h2 id="create-a-lot-or-serial-number" tabindex="-1">Create a lot or serial number <a class="header-anchor" href="#create-a-lot-or-serial-number" aria-label="Permalink to &quot;Create a lot or serial number&quot;">​</a></h2><p>Scenario: register a serial number for a finished <strong>Business Laptop</strong> that is tracked <strong>By Unique Serial Number</strong>.</p><ol><li>Open <code>Manufacturing → Products → Lots / Serial Numbers</code>.</li><li>Click <strong>New Lot / Serial Number</strong>.</li></ol>',4)),o(r,{src:"/images1/manufacturing/lot_create_button.png",alt:"Lots list with the New Lot / Serial Number button highlighted"}),e[2]||(e[2]=s("ol",{start:"3"},[s("li",null,"Fill the form.")],-1)),o(r,{src:"/images1/manufacturing/lot_create_form.png",alt:"Create Lot form filled: Name MC-LAP-0001, Product Business Laptop, Company My Company, Reference, Description"}),e[3]||(e[3]=t('<ul><li><strong><em>Name:</em></strong> The lot or serial code. Required.</li><li><strong><em>Product:</em></strong> The tracked product. Required. You cannot change it after the number has moved.</li><li><strong><em>Company:</em></strong> The owner company.</li><li><strong><em>Reference:</em></strong> An internal reference, if it differs from the maker&#39;s number.</li><li><strong><em>Description:</em></strong> Free notes.</li></ul><ol start="4"><li>Click <strong>Create</strong>, or <strong>Create &amp; create another</strong> to add more.</li></ol><h2 id="lots-on-manufacturing-orders" tabindex="-1">Lots on manufacturing orders <a class="header-anchor" href="#lots-on-manufacturing-orders" aria-label="Permalink to &quot;Lots on manufacturing orders&quot;">​</a></h2><p>A work order shows the <strong>Lot/Serial Number</strong> of the product it builds. On the MO list you can show the <strong>Lot/Serial Number</strong> column. See <a href="./work-orders.html">Work orders</a>.</p><p>Tracking brings two checks when you finish an MO.</p><ul><li><strong>Unique serial number.</strong> A finished serial number can be used once. If you reuse it, Aureus says &quot;This serial number for product :product has already been produced&quot;.</li><li><strong>Numbers for consumed parts.</strong> If a component is tracked and no lot or serial is chosen, Aureus says &#39;You need to supply Lot/Serial Number for products and &quot;consume&quot; them&#39; and lists the products.</li></ul><p>The product name replaces <code>:product</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Create the serial numbers before you finish the order, so each one is ready to pick.</p></div><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>On the list, <strong>View</strong> shows the number. <strong>Edit</strong> changes its details. <strong>Delete</strong> removes a number. Aureus refuses if the number is in use: &quot;The lot cannot be deleted because it is currently in use.&quot;</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../inventories/tracking/lots-and-serial-numbers.html">Lots and serial numbers (Inventory)</a></li><li><a href="./produce-and-consume.html">Produce and consume</a></li><li><a href="./manufacturing-orders.html">Manufacturing orders</a></li><li><a href="./../basic-setup/configure-product.html">Configure product</a></li></ul>',12))])}const _=n(u,[["render",c]]);export{f as __pageData,_ as default};
